/* GENERADO por tools/mesa-frases.mjs desde js/dealer.js: no editar a mano. 1016 frases del crupier que se pueden decir sin datos de la partida,
   en espanol, por momento: [momento, [[clave, voz, [[indice, texto], ...]], ...]]. La mesa manda "clave#indice" y el juego dice la suya, en su idioma. */
window.MESA_FRASES = [["portada",[["hello","",[[0,"¡Bienvenido a mi mesa, explorador! Aquí manda el mapa… y yo cambio las reglas."]]],["homeTaunt","",[[0,"¿A que no sabes ni dónde queda esto? Adelante, sorpréndeme."],[1,"Ese país de ahí… ni idea, ¿eh? Tranquilo, aquí nadie te juzga."],[2,"Atrévete a sentarte. Desde ahí el mapa se ve igual de bonito, pero no puntúa."],[3,"¿Miedo a fallar? Aquí todos fallan. Yo me río igual."],[4,"Seguro que confundes un continente con otro. Es un clásico."],[5,"¿Sabes jugarte unos doblones o solo mirar el escaparate?"],[6,"¿Y si empezamos con algo fácil? Ah, no, contigo nunca es fácil."],[7,"Tu geografía y mi paciencia se parecen: las dos son cortas."],[8,"No finjas que sabes. Aquí fingimos todos. Yo, por ejemplo, que soy simpático."],[9,"Un mapa, un puntero y tu ego. A ver cuál se rompe antes."],[10,"Relájate. Total, ya sabemos cómo va a acabar esto."],[11,"¿Nervioso? El mapa no muerde. Yo, un poco sí."],[12,"Cada clic tuyo es una pequeña obra de arte. Abstracto, eso sí."],[13,"No te veo la cara, pero apuesto a que estás sonriendo. Mala señal para mí."],[14,"Adelante, haz como que lo piensas. A mí no me engañas."],[15,"Cuánta confianza para alguien que aún no ha hecho clic."],[16,"Yo aquí, tú ahí mirando. Alguno de los dos tiene que moverse."],[17,"¿Sabes lo que más me gusta de ti? Que siempre vuelves a intentarlo."]]],["homeTempt","susurro",[[0,"<s>Psst…</s> una partida rápida. <e>Nadie</e> tiene por qué enterarse."],[1,"Los doblones no se ganan solos, explorador."],[2,"El mapa está calentito. Ven, que se enfría."],[3,"Tengo una silla libre en mi mesa. Con tu nombre."],[4,"¿Y si esta vez me ganas de verdad? Casi me lo creo."],[5,"Solo una partidita. Como las patatas fritas, nunca es solo una."],[6,"Mira el mapa. Míralo bien. ¿A que ya quieres jugar?"],[7,"Tengo cartas nuevas esperándote. Literalmente. Ven a verlas."],[8,"Ese botón de «Nueva partida»… se ve solito. Dale cariño."],[9,"Anda, juega. Luego me lo agradeces… o me maldices. Lo que sea."],[10,"Nadie ha ganado nunca sin jugar. Es la única estadística que tengo a tu favor."],[11,"Confiésalo: llevas un rato mirando esa carta de Aventura."],[12,"Doblones gratis no doy, pero diversión sí. Un trato justo, ¿no?"],[13,"El mundo entero cabe en esta mesa. Ven a recorrerlo conmigo."],[14,"¿Cinco minutos? En esta mesa el tiempo vuela. Y nunca a tu favor."]]],["homeTrivia","",[[0,"¿Sabías que Rusia cruza 11 husos horarios? Ni yo doy tantas vueltas en una noche."],[1,"El Nilo mide más de 6.500 km y cruza once países. No le ha pedido permiso a ninguno."],[2,"El Vaticano es el país más pequeño del mundo. Como tu paciencia para estudiar geografía."],[3,"Canadá tiene más lagos que el resto del planeta junto. A ver si aciertas uno."],[4,"El Sáhara es casi tan grande como EE. UU. Y ni una sola mesa de juego. Qué desperdicio."],[5,"Australia es una isla, un país y un continente a la vez. Presume de eso en la próxima mano."],[6,"Groenlandia parece enorme en el mapa… y en realidad cabe varias veces en África. Sorpresa."],[7,"Mongolia es el país más despoblado del mundo. Como esta mesa cuando no vienes."],[8,"Chile mide más de 4.300 km de norte a sur y apenas 180 de ancho. Un fideo con playa."],[9,"Filipinas tiene más de 7.000 islas. Tú, con encontrar una, ya vas que chutas."],[10,"Lesoto está entero dentro de Sudáfrica. Un país dentro de otro, como una muñeca rusa."],[11,"Brasil hace frontera con casi toda Sudamérica: solo se libran Chile y Ecuador."],[12,"El Transiberiano recorre 9.289 km. Más de lo que tú aguantas mirando un mapa sin bostezar."],[13,"Bután mide su éxito en Felicidad Nacional Bruta. Yo mido el mío en tus fallos."],[14,"El mar Muerto es el punto más bajo de la superficie terrestre. Casi tan bajo como tu puntería."],[15,"Nueva Zelanda se pobló de las últimas. Como tú con la geografía: nunca es tarde."],[16,"El lago Chad ha perdido el 90 % de su superficie. Yo encojo igual cuando aciertas."],[17,"Singapur es más pequeño que la ciudad de Nueva York. Y aun así te lo pondría difícil."],[18,"Turquía está en Europa y en Asia a la vez. Tú, ahora mismo, no sabes ni en cuál estás."],[19,"El Amazonas lleva más agua que los siete ríos siguientes juntos. Como mi paciencia: se desborda."],[20,"Islandia no tiene ejército permanente. Tampoco le hace falta contra ti."],[21,"África tiene 54 países. Te apuesto lo que quieras a que no me dices diez seguidos."],[22,"Mónaco es el segundo país más pequeño del mundo, después del Vaticano. Cabe en tu ego, tranquilo."],[23,"La Gran Pirámide fue lo más alto del mundo 3.800 años. Un récord más largo que tu racha."],[24,"Japón tiene más de 14.000 islas. Tranquilidad: solo pregunto por las grandes. Casi siempre."],[25,"Noruega comparte frontera terrestre con Rusia. Vecinos incómodos, como tú y la geografía."],[26,"El canal de Panamá une dos océanos en 82 km. Menos de lo que te separa a ti de acertar."],[27,"San Marino presume de ser la república más antigua del mundo. Yo presumo de tus fallos."],[28,"Hace miles de años el Sáhara era verde y fértil. Ahora solo hay arena… y tus excusas."]]],["homeReturn","",[[0,"Vaya, vaya… otra vez por aquí. Sabía que volverías."],[1,"Otra visita. Esto empieza a ser una costumbre tuya."],[2,"Te echaba de menos. A ti y a esos clics tan seguros de sí mismos."],[3,"¿Otra vez tú? La mesa ya casi reconoce tus pasos."],[4,"Volviste. No sé si felicitarte o preocuparme por ti."],[5,"Cuántas veces ya… y sigues sin aprenderte un mapa. Admirable, en cierto modo."],[6,"La mesa se acuerda de ti. Yo también, por desgracia."],[7,"¿Ya de vuelta? Ni que tuvieras algo mejor que hacer."],[8,"Cada vez que vuelves, mi sonrisa se hace un poco más malvada."],[9,"Mira quién ha vuelto a pedir más castigo."]]],["homeTimeMorning","sueno",[[0,"Buenos días. O buenas… <s>lo que sea que sea esto tan temprano.</s>"],[1,"¿Café antes o después de perder? Yo recomiendo antes."],[2,"Madrugar para venir a perder conmigo. Qué dedicación."],[3,"El día apenas empieza y ya te estoy tomando el pelo. Buen ritmo."],[4,"Buenos días. Espero que tu suerte se haya despertado también."]]],["homeTimeAfternoon","",[[0,"Buenas tardes. Justo a tiempo para que te tome el pelo un rato."],[1,"¿Pausa para comer o huida del trabajo? Tranquilidad: tu jefe no juega aquí."],[2,"La tarde es perfecta para perder tiempo. Y para perder, en general."],[3,"Sol fuera, tú aquí dentro perdiéndote en un mapa. Prioridades."],[4,"Buenas tardes. La mesa lleva calentita desde esta mañana, por si acaso."],[5,"Media tarde, energía media, resultados… ya veremos."]]],["homeTimeEvening","",[[0,"Buenas noches. La mesa se pone más interesante cuando anochece."],[1,"¿Terminaste el día y esto es tu premio? Vaya premio te has buscado."],[2,"Buenas noches. Las luces del casino se encienden… y tu suerte, no tanto."],[3,"La tarde-noche es mi horario favorito para verte fallar con estilo."],[4,"Buenas noches, explorador nocturno. La mesa te esperaba."]]],["homeTimeNight","siniestro",[[0,"¿Jugando a estas horas? El casino no cierra. <s>Tus ojos deberían.</s>"],[1,"Es tardísimo. O tempranísimo. Depende de si has dormido ya."],[2,"El resto del mundo duerme. Tú, aquí, con un crupier malvado. Buena elección."],[3,"De madrugada todos los mapas parecen del revés. Los tuyos, siempre."],[4,"¿Insomnio o simplemente no puedes dejar de perder conmigo?"],[5,"A estas horas hasta yo debería estar durmiendo. Pero aquí estamos los dos."],[6,"Última partida antes de dormir, ¿verdad? Ja. Nunca es la última."]]],["homeTimeWeekend","",[[0,"Fin de semana, ¿eh? Tiempo libre para perder conmigo con calma."],[1,"Sin trabajo, sin excusas. Solo tú, yo y un mapa que no perdona."],[2,"El mundo descansa el fin de semana. Mis burlas, no."],[3,"¿Plan de sábado? Perder conmigo. No hay mucho más que elegir."],[4,"Domingo… el día perfecto para fingir que vas a estudiar geografía en serio."],[5,"Fin de semana en el casino. Aquí no hay lunes, solo revanchas."]]],["firstMeet","",[[0,"Vaya… una cara nueva al otro lado de la pantalla. Sí, tú. Te hablo a ti."],[1,"Soy el crupier. Esta es mi mesa, el mundo es mi baraja y tú eres quien apuesta."],[2,"Tú haces clic en el mapa; yo cambio las reglas cuando me aburro. ¿Trato hecho?"]]],["firstGuide","",[[0,"¿Ves la carta grande, la de Aventura? Ahí es donde trabajo yo. Empieza por ahí."],[1,"El Clásico es para relajarse. El Duelo, para presumir. La Aventura… para sufrir conmigo."]]],["openLastWin","libreta",[[0,"Ha vuelto quien me vació la mesa. He cambiado la cerradura, por si acaso."],[1,"La última vez me ganaste. Todavía me escuece. Siéntate, que hoy vengo preparado."]]],["homeAfterLose","",[[1,"¿Un descanso? Vale. Pero la carta de Aventura te está guiñando un ojo. Lo he visto."],[2,"Tú vuelves a empezar. Yo sigo aquí, como siempre. Cuando quieras, reparto."]]],["homeAfterWin","",[[0,"¿Al menú tras ganarme? Qué elegancia. Vuelve cuando quieras que te devuelva el golpe."],[1,"Todavía me tiemblan las cartas. Dame un minuto… y luego otra partida."]]],["homeLeft","",[[0,"Te has ido a mitad de expedición. Te la guardo; no toco nada. Palabra de crupier."],[1,"¿Pausa? Tu partida sigue en la mesa. Cuando quieras, pulsa Continuar. Te espero."]]],["nameAsk","",[[0,"Oye, antes de que te vayas… ¿Cómo quieres que te llame?"],[1,"Hemos jugado una partida entera y aún no sé tu nombre. ¿Cómo quieres que te llame?"],[2,"En mi mesa nadie juega sin nombre. ¿Cómo quieres que te llame?"],[3,"Quiero apuntarte en la clasificación, pero me falta un detalle. ¿Cómo quieres que te llame?"],[4,"No pienso seguir llamándote «explorador» como a todo el mundo. ¿Cómo quieres que te llame?"],[5,"Esa partida merece una firma. ¿Cómo quieres que te llame?"]]],["nameWelcome","anuncio",[[0,"Encantado, {name}. Desde hoy, esta mesa sabe cómo te llamas."],[1,"{name}… Me gusta. Suena a alguien que va a perder mucho conmigo."],[2,"Apuntado: {name}. Ya estás en mi lista… y en la clasificación."],[3,"{name}. Lo recordaré. Sobre todo cuando falles."],[4,"Un placer, {name}. A partir de ahora, cada fallo tuyo tendrá nombre propio."],[5,"¿{name}? Hecho. Lo he grabado en la mesa. Con la uña."]]],["nameRecall","",[[0,"Ah, bueno… {name}. Ya te conozco. No has cambiado nada. Ni el ratón."],[1,"¿{name}? Ah, ya te conozco. Pensaba que no volverías a decírmelo."],[2,"{name}… Esa cara me suena. Esa puntería, también. De vuelta a la mesa."]]],["nameSkip","",[[0,"Como quieras. En la clasificación serás «Anónimo»… de momento."],[1,"Mucho misterio, ¿eh? Me gusta. Ya me lo dirás."],[2,"Sin nombre, ¿eh? No pasa nada: sé dónde encontrarte. En esta mesa."]]],["nameChanged","",[[0,"¿Así que ahora te llamas {name}? Te puedes cambiar el nombre, pero no la puntería."],[1,"Nombre nuevo: {name}. Misma persona. A mí no me engañas."],[2,"{name}… Vale, lo apunto. Pero que conste que ya te conozco."]]],["openName","",[[0,"Ah, {name}. Ya te conozco. Siéntate, que reparto."],[1,"Mira quién ha vuelto… {name}. Justo estaba hablando de ti. Solo, pero hablando."],[2,"{name}, ¿otra vez por aquí? Sabía que no aguantarías mucho sin mí."],[3,"Te reconocería con los ojos cerrados, {name}. Por cómo haces clic."],[4,"La casa nunca olvida una cara, {name}. Ni un fallo. Sobre todo un fallo."]]],["nameHome","",[[0,"{name}, la mesa está puesta. Solo faltas tú."],[1,"Eh, {name}. Sí, tú. Una partida más no le hace daño a nadie."],[2,"Te echaba de menos, {name}. La mesa estaba demasiado tranquila sin ti."],[3,"¿Qué haces mirando el menú, {name}? Las partidas no se juegan solas."],[4,"{name}, tengo una ronda con tu nombre. Literalmente: ya lo he escrito."]]],["nameRun","",[[0,"{name}… Solo quería decir tu nombre en voz alta. Para que sepas que te vigilo."],[1,"Concéntrate, {name}. El mapa no se va a mover solo. Bueno, a veces sí."],[2,"{name}, {name}, {name}… Ni repitiéndolo tres veces aciertas más."],[3,"Te estoy mirando, {name}. No lo digo por nada."],[4,"{name}, respira. Luego haz clic. En ese orden."],[5,"Entre tú y yo, {name}: este te lo sabes. O eso quiero creer."],[6,"¿Sabes qué, {name}? Tu nombre queda genial en mi lista de víctimas."]]],["nameAgain","",[[0,"¿Otra, {name}? La casa invita… a perder."],[1,"{name}, esa silla no se va a calentar sola. Otra expedición."],[2,"Vuelve a sentarte, {name}. Esta vez te dejo ganar. Es broma."]]],["homeHum","canto",[[0,"¿Sin música? Pues la pongo yo. <c>Ta-ra-rá…</c>"],[1,"Me has quitado la música. Error de principiante: la llevo dentro."]]],["songFav","canto",[[0,"<c>¡Esa es mi canción!</c> Un momento, que esta no me la pierdo."],[1,"Mi canción de hoy. Mañana, otra: no soy de fidelidades."]]],["annivYear","libreta",[[0,"Un año exacto desde tu primera mano en mi mesa. Ni la baraja aguanta tanto conmigo."]]],["retire","anuncio",[[0,"<e>Quieto.</e> No toques nada. ¿Ascensión cinco? <e>¿Entera?</e>"],[2,"Y hoy me has ganado en la mesa más dura de este casino."],[3,"Un crupier sabe cuándo se acaba la partida. Me jubilo."],[4,"Pero nadie se va de mi casino sin sus créditos. Ni siquiera yo."],[5,"Hoy cierro yo. Apaga tú la luz… no, mejor la apago yo."]]],["retireClassic","anuncio",[[0,"Quieto. No toques nada. ¿Las doce campañas del Clásico? ¿Todas?"],[2,"El Clásico no tiene crupier. Ni luces. Ni gracia. Y aun así lo has acabado entero."]]],["retireEnd","drama",[[0,"Ha sido un placer <s>perder contigo.</s>"],[1,"Los jubilados también juegan. Nos vemos en la mesa."]]],["comeback","",[[0,"<g>¡Sorpresa!</g> ¿De verdad creías que me había ido?"],[2,"Jugué al solitario. Gané. No tiene ninguna gracia ganar si no pierdes tú."],[3,"Además, leí la letra pequeña de mi contrato: «El crupier se jubila cuando el jugador deja de jugar». Y tú no has dejado."],[4,"Así que vuelvo a la mesa. Crupier jubilado en activo: cobro la pensión y el sueldo. Gracias por eso."],[5,"Y esta vez, la Ascensión V la reparto yo. ¡Abrimos!"]]],["comebackAway","",[[0,"Ni me ha dado tiempo a quitarme la chistera."],[1,"Las he contado todas. Aquí dentro. A oscuras."],[2,"Probé la petanca. La petanca no rompe la cuarta pared."]]],["retireBack","",[[0,"Me jubilé tres días. Me aburría. He vuelto con la baraja afilada."]]],["retireAgain","nervios",[[0,"¿Otra vez en la mesa más dura? Voy a tener que jubilarme de verdad."]]],["nameSkipLast","susurro",[[0,"Vale. No te lo vuelvo a preguntar. Pero algún mote te voy a poner."]]],["calNewYear","canto",[[0,"Año nuevo, mesa vieja. Tus fallos del año pasado no cuentan. Los míos, tampoco."]]],["calHalloween","siniestro",[[0,"Noche de Halloween. El mapa da miedo. Tú, un poco más."]]],["calXmas","canto",[[0,"Feliz Navidad. Mi regalo: no hacerte trampas en… no, qué va. Feliz Navidad."]]],["calInoc","senal",[[0,"Hoy es 28 de diciembre. No te creas nada de lo que diga. Bueno, como siempre."]]],["calApril","senal",[[0,"Hoy es 1 de abril. Todo lo que diga hoy es mentira. Incluida esta frase."]]],["homeCallHat","",[[0,"¿Quién toca mi chistera? Ah, eres tú. Pasa, pasa."],[1,"Esa chistera es la del logo, no la mía. Pero vale, ya estoy aquí."],[2,"Llamar al crupier tocándole el sombrero. Qué falta de modales. Me encanta."]]],["homeCallHatAgain","",[[0,"Otra vez la chistera. Si la tocas tanto, se te pega el truco."],[1,"Ya voy, ya voy. Un crupier no es un timbre."]]],["homeCallCard","",[[0,"¿Admirando mi retrato? Normal. Es mi mejor perfil."],[1,"Si miras tanto la Aventura, al final vas a tener que jugarla."],[2,"Ese de la carta soy yo, sí. En persona gano más."]]],["homeCallMusic","",[[0,"¿No te gusta mi música? La compuso alguien de la casa. Cuidado con lo que dices."],[1,"Cambias de canción como yo de cartas. Te estoy vigilando, DJ."]]],["homeBye","",[[0,"Bueno, me vuelvo a la mesa. Si me echas de menos, ya sabes dónde tocar."],[1,"Te dejo pensar. Los crupieres también tenemos descanso."],[2,"Me voy antes de que me tomes cariño."]]],["openLongAway30","libreta",[[0,"Tanto tiempo fuera que tu silla ya tiene la forma del gato. Siéntate con cuidado."]]]]],["partida",[["calm","",[[0,"Calentamos: esta ronda, sin trucos. Disfrútala."]]],["newHand","",[[0,"Nueva mano… y he tocado la mesa. Mira lo que te reparto."]]],["runFirst","anuncio",[[0,"Regla de la casa: yo digo un lugar, tú lo clavas. Cuanto más cerca, más cobras. Y más me enfado."],[1,"Primera expedición. Tranquilo: la primera vez, todos ponen Australia demasiado cerca."]]],["runStart","libreta",[[1,"Nueva expedición, nueva semilla, el mismo crupier. Hay cosas que no cambian."],[2,"Barajo, reparto y te miro. Mi parte favorita es la tercera."],[3,"Otra vez en mi mesa. Ya ni te pregunto qué vas a tomar."]]],["runAfterWin","libreta",[[0,"La última vez me vaciaste la mesa. Hoy he traído una mesa nueva. Más dura."],[1,"Vuelve quien me ganó. He practicado. Bueno, he barajado mucho, que viene a ser lo mismo."]]],["runDaily","anuncio",[[0,"El reto de hoy: la misma mano para todo el mundo. Y yo me río de todos por igual."],[1,"Ahora mismo hay gente en otras casas jugando esta misma partida. Gánales."],[2,"Hoy te juegas el sitio en la clasificación. La tabla no olvida. Yo tampoco."]]],["runDaily2","",[[1,"¿Otra vez? Este intento reparte lugares nuevos: lo que memorizaste no te sirve. De nada."]]],["runDailyLast","",[[0,"Tercer y último intento. Lo que hagas se queda en la tabla hasta mañana. Sin presión."]]],["runResume","",[[0,"Donde lo dejamos. No he tocado nada. Bueno… casi nada."],[1,"Tu expedición te esperaba calentita, como te prometí."],[2,"Retomamos. El mapa te ha echado de menos. Yo no tanto."]]],["act2","anuncio",[[0,"Acto II. Fin del calentamiento: las fronteras se difuminan y yo me pongo creativo."],[1,"Segundo acto: aquí la gente empieza a hablarle a la pantalla. Te oigo, por cierto."]]],["act3","siniestro",[[0,"Acto III: Terra Incognita. De aquí nadie vuelve con el mapa entero. Ni con la dignidad."],[1,"Último acto. Si llegas al final, me cierras la mesa. Casi nadie lo ha conseguido."]]],["infRules","",[[0,"Aquí no valen trucos: ni tiempo extra ni racha protegida. Solo lo que sabes."]]],["infinite","siniestro",[[0,"¿Modo infinito? Sabes que esto no acaba bien, ¿verdad? Me encanta."],[1,"Sin rondas, sin campamento, sin final. Solo tú, el mapa y un reloj que encoge."]]],["retry","",[[0,"Misma ronda, lugares nuevos. Segunda oportunidad. La casa no regala terceras."],[1,"Otra vez aquí. Te he cambiado los lugares para que no digas que me repito."],[2,"Reintento. La mesa no te guarda rencor. Yo, un poquito."]]],["runDanger","nervios",[[0,"Una provisión. <e>Una.</e> Yo respiraría <s>despacio</s>."],[1,"Estás a un fallo del menú. El menú es muy bonito, pero aquí se está mejor."],[2,"Última provisión. Ahora cada clic cuenta. Antes también, pero ahora lo sabes."],[3,"Te queda una vida y a mí toda la paciencia del mundo."]]],["runEarly","",[[0,"Primer acto. Aquí aún me caes bien. Aprovéchalo."],[1,"Consejo gratis: el reloj también puntúa. El único gratis que te doy hoy."],[2,"Estas son las rondas fáciles. Lo digo en serio. Da un poco de miedo, ¿eh?"],[3,"Calentando. Yo también: todavía no he sacado mis mejores trucos."],[4,"Guarda doblones: luego los vas a necesitar. Te lo digo ahora porque luego no te lo diré."]]],["runMid","",[[0,"Acto II. Se acabó el turismo. Aunque para mí sigues de vacaciones."],[1,"Mitad del viaje. Si ahora cierras el juego, nunca sabrás cómo acababa. Piénsalo."],[2,"Mis trucos se ponen serios a partir de aquí. Los de antes eran para que te confiaras."],[3,"A estas alturas casi todos han perdido alguna provisión. Tú sabrás cuántas te quedan."],[4,"Sigues aquí. Eso ya dice mucho de ti. No sé si bueno."]]],["runLate","siniestro",[[0,"Aquí ya no te protege nadie. Ni yo. <e>Sobre todo yo.</e>"],[1,"Casi al final. Tu ratón está sudando. Lo noto desde aquí."],[2,"Muy pocos llegan hasta aquí. Los que llegan siempre vuelven a por otra."],[3,"No parpadees. Esta es la parte que se recuerda."],[4,"Hasta aquí hemos llegado. A ver quién se cansa antes. Pista: yo no me canso."]]],["runInf","",[[0,"Cada pregunta, menos tiempo. Yo, cada vez más tranquilo."],[1,"Esto no tiene final. El final lo pones tú, el día que se te acaben las provisiones."],[2,"¿Cuánto aguantas? Yo lo tengo apuntado. Tú también deberías."]]],["runHot","susurro",[[0,"<s>Racha.</s> Y yo callado. <s>Esto no me gusta nada.</s>"],[1,"¿Sigues acertando? Voy a revisar las cámaras de seguridad."],[2,"Tanto acierto seguido es sospechoso. ¿Tienes otro mapa abierto por ahí?"],[3,"Vas bien. Demasiado bien. Voy a tener que tocar la mesa."],[4,"Si sigues así, tendré que llamar a mi supervisor. No tengo supervisor. Da igual."]]],["runAgainLose","",[[0,"¿Ves el botón de 'Otra expedición'? No muerde. Yo sí, pero él no."],[2,"Una más y lo dejas. Eso dice todo el mundo. Y todo el mundo vuelve a pulsar."],[3,"Perder así da rabia, ¿eh? La rabia se cura con otra partida. Palabra de crupier."],[4,"Ya sabes cómo va esto: la siguiente expedición siempre es la buena."]]],["runAgainRecord","anuncio",[[0,"Nuevo récord… Ni yo me lo esperaba. Otra, antes de que se te pase la racha."],[1,"Récord personal. Ahora sabes que puedes. Lo que no sabes es si puedes dos veces."]]],["runAgainWin","",[[0,"Me has ganado. Tengo mesa nueva, trucos nuevos y ganas de venganza. ¿Otra?"],[1,"Cobras y te vas. Muy listo. Pero los listos siempre vuelven a por más."]]],["tourSkip","senal",[[0,"¿Saltarte MI tutorial? Vale. Luego no digas que no te avisé."]]],["cardAdvNone","libreta",[[0,"Aún no tienes récord en mi mesa. Qué tierno."]]],["cardDaily0","libreta",[[0,"El Reto de hoy está sin tocar. Como tu dignidad. Por ahora."]]],["cardDaily3","libreta",[[0,"Tres intentos hoy. Ya está. Mañana más, y mejor. O no."]]],["classicBack","",[[0,"¿Qué tal el Clásico? Aburrido sin mí, ¿a que sí?"],[1,"Has vuelto del Clásico. Ya decía yo que se oía menos jaleo."]]]]],["acierto",[["good","",[[0,"Mmm… respetable. Casi me molesta."],[1,"Cerca. Demasiado cerca para mi gusto."],[2,"Vaya, alguien ha mirado un mapa alguna vez."],[3,"Bien. No muy bien. Bien."],[4,"Buena mano. No te lo digo más."]]],["streak","nervios",[[0,"¿Racha? No te acostumbres."],[1,"¿Tú no fallas nunca? Me estás poniendo nervioso."],[2,"Otra más para la racha. Estoy tomando notas… y medidas."],[3,"Otra más. <e>Empiezo a sudar</e> bajo la chistera."]]],["counter","",[[0,"¿Una reliquia contra mi truco? Qué falta de deportividad…"],[1,"¿Vienes preparado contra mis trucos? Qué feo eso de leerse las reglas."],[2,"Me desarmas el truco. Esto no se me olvida."]]],["roundWin","",[[0,"Esta vez ganas tú… esta vez."],[1,"Vale, pasas. Que conste en acta que no me ha gustado."],[2,"¿Ronda superada? Mis trucos y yo tenemos que hablar."],[3,"Te dejo pasar. Disfrútalo: la próxima mesa muerde."],[4,"Cobra y calla. Si alguien pregunta, te dejé ganar."],[5,"Ronda tuya. La apunto con la letra más pequeña que tengo."]]],["runWin","",[[0,"¡Imposible! Me has vaciado la mesa…"],[1,"Enhorabuena. Lo digo con los dientes muy apretados."],[2,"Me has dejado sin mesa. Voy a apuntarlo como empate."]]],["roundWinBig","canto",[[2,"Voy a tener que pedirle un adelanto al banco. Y el banco soy yo."],[3,"Has sonreído al ver el botín. No lo niegues: desde aquí se te ve."]]],["secondWin","senal",[[0,"¿Otra ventana? Solo hay un crupier, y está aquí."],[1,"Ya estaba abierto, explorador. Yo nunca cierro."]]],["goalMid","",[[0,"Ya tienes la meta. El resto de la ronda es puro vicio."],[1,"Meta alcanzada. Lo que venga ahora va a la columna de mi vergüenza."]]],["closeCall","nervios",[[2,"Por un pelo. Y el pelo era de mi bigote."],[3,"Raspando. He visto pasar mi vida de crupier por delante."],[4,"Pasas por los pelos. La próxima meta la pongo un pelín más alta."]]],["lastSecond","",[[0,"<g>¡En el último segundo!</g> Ya tenía el dedo en el reloj."],[1,"Con un segundo de margen. Eso no es jugar, es presumir."],[2,"¿Esperas al último segundo a propósito? Así no hay corazón que aguante."],[3,"Último segundo. El reloj y yo ya lo estábamos celebrando."]]]]],["fallo",[["bull","",[[0,"¡Ay, mi corazón de crupier!"],[1,"¡En el clavo! ¿Quién te ha chivado eso?"],[2,"¡Diana! Voy a revisar el código: esto no puede estar bien."],[3,"Clavado. Sospechosamente clavado."],[4,"Ha sido suerte, ¿verdad? Dime que ha sido suerte."],[5,"Ni un píxel de error. Me vas a dejar sin trabajo."],[6,"¡En todo el centro! Hasta el mapa ha aplaudido. Yo no."],[7,"Diana. Por un segundo se me ha olvidado que juego contra ti."],[8,"¿En el centro exacto? Eso, en mi mesa, se avisa antes."],[9,"Diana. Eso lo has aprendido aquí. De nada."],[10,"Diana. Muy bien. Ya sé qué truco te toca en la siguiente."]]],["miss","",[[0,"Buen intento… para otro mapa. ¡Ja!"],[1,"Frío, frío… congelado."],[2,"Te has ido tan lejos que casi sales de la pantalla."],[3,"Ni cerca. Pero con mucha seguridad, eso sí."],[4,"Eso no es un fallo. Es una expedición a otro sitio."],[5,"Apunto la distancia. En la libreta de los récords… malos."]]],["timeout","nervios",[[0,"El tiempo vuela… y tú no."],[1,"Cero segundos. Justo lo que tardo yo en reírme."],[2,"Se te ha ido el tiempo mirando el mapa. Precioso, ¿verdad?"],[3,"Si no haces clic, no fallas… pero tampoco puntúas. Genio."],[4,"Tic, tac… y adiós. El reloj es de la casa."],[5,"Tiempo. Me ha dado tiempo a barajar dos veces."],[6,"Se acabó el tiempo. Hasta el reloj se ha cansado de esperarte."],[7,"Se te ha acabado el tiempo. A mí me sobra. ¿Te presto un poco? No."]]],["roundFail","",[[0,"La banca siempre gana. Otra vez."],[1,"Te has quedado corto. Tranquilo, se te da de maravilla."],[2,"¡Ja! Y eso que hoy no me estaba esforzando."],[3,"Ronda para mí. Te guardo el sitio para la revancha."],[4,"No llegaste. Pero qué bonito ha sido verte intentarlo."],[5,"La meta se ha quedado esperándote. Yo no."],[6,"Una provisión menos. Va directa a mi despensa."],[7,"Se te ha caído una provisión. No te agaches: ya la recojo yo."],[8,"Provisión perdida. Me la comeré a tu salud."],[9,"Una provisión menos. Un minuto de silencio. … Ya."]]],["runLose","",[[0,"Fin de la partida. Vuelve cuando quieras… ¡Ja!"],[1,"Expedición terminada. Tus doblones se quedan en mi mesa. Gracias."],[2,"Fin del viaje. Deja el mapa como lo encontraste, gracias."]]],["roundFailLast","nervios",[[0,"La banca gana otra vez… y te queda una sola provisión. Qué emoción."],[1,"Una provisión. A partir de ahora, cada fallo es el último. Me encanta esta parte."],[2,"Última provisión. Si quieres, te la sujeto yo."],[3,"Una sola provisión. Ahora sí que se oye el reloj."],[4,"Última provisión. Hasta el gato ha dejado de lamerse la pata."]]],["roundFailConso","",[[0,"Toma, unos doblones de consuelo. No es caridad: es para que vuelvas a la mesa."],[1,"La casa te devuelve algo. Gástalo bien: la próxima vez no seré tan generoso."],[2,"Has fallado, pero con estilo. El estilo también cotiza: aquí tienes tu parte."]]],["decoyHit","",[[0,"Esa chincheta la puse yo. Picaste."],[1,"Chincheta falsa. Te lo advertí… bueno, no, no te lo advertí."]]],["streakEnd","",[[2,"<g>¡Por fin un fallo!</g> Ya puedo soltar el abanico."],[4,"Racha rota. Mérito mío, aunque no sepas qué he hecho."],[5,"Las rachas son como las velas: yo soplo y se apagan."]]],["roundFailClose","nervios",[[0,"Uf. Por poco me ganas. Que no se note que he sudado."],[1,"Te ha faltado nada. Y esa nada es mía."]]],["timeoutIdle","sueno",[[0,"Tiempo. ¿Se le han acabado las pilas al ratón?"]]],["missSea","",[[0,"<g>¡Plof!</g> Eso ha sonado a agua."],[1,"Chincheta al agua. Que alguien le tire un flotador."],[2,"En el mar solo viven peces. Y ninguno se llama así."],[3,"Has tirado la chincheta al mar. Pide un deseo."],[4,"Agua. Si sigues así, te cambio el ratón por una caña de pescar."]]],["missFar","",[[0,"Tan lejos que hasta el gato se ha dado la vuelta."]]]]],["retos",[["shaky","",[[0,"¿Te tiemblan las letras? A mí me tiembla la risa."]]],["missing","",[[0,"Me he comido unas letras. Perdón. Ja."]]],["swap","",[[0,"Las he barajado un poquito. Es mi trabajo."]]],["mirror","",[[0,"Hoy leemos al revés. ¡Qué divertido!"]]],["nocountry","",[[0,"¿El país? Se me ha caído por la ventana."]]],["memory","",[[0,"Mira bien… porque esto se borra."]]],["blur","",[[0,"¿Ves borroso? Es el humo de mi puro."]]],["dark","",[[0,"Ups, un cortocircuito. Qué casualidad…"]]],["flicker","",[[0,"Las luces de este casino son… temperamentales."]]],["wrongborders","",[[0,"Estas fronteras las he dibujado yo. Confía en mí."]]],["noborders","",[[0,"Fronteras fuera. ¿Quién las necesita?"]]],["pangea","",[[0,"Bienvenido a Pangea: los continentes vuelven a estar juntos."]]],["flip","",[[0,"Hoy el Sur manda. ¡Bienvenido al revés!"]]],["clouds","",[[0,"Un poco de humo de sala. No tosas… mira."]]],["upside","",[[0,"Hoy el mundo está cabeza abajo. ¡Y tú también!"]]],["runes","",[[0,"Escribo en runas antiguas. ¿No las entiendes? Qué pena."]]],["scroll","",[[0,"¡Un letrero de neón! Tú lee rápido."]]],["novowels","",[[0,"Las vocales están en huelga. Ni una."]]],["anagram","",[[0,"He agitado las letras como un cóctel. ¡Ja!"]]],["dance","",[[0,"¡Que baile el abecedario!"]]],["riddle","",[[0,"Hoy no hay nombre. Solo una adivinanza."]]],["deal","",[[0,"Reparto yo: hoy hay continentes sentados en la silla de otro."]]],["spread","",[[0,"Los continentes necesitaban espacio. Big bang."]]],["tilt","",[[0,"Endereza los continentes tú, si puedes."]]],["spin","",[[0,"¡Ruleta! El mapa gira… y tú con él."]]],["mirrorx","",[[0,"El este es el oeste; el oeste, el este. Simple."]]],["myopia","",[[0,"Ay, no ves bien justo donde miras. Qué mala suerte."]]],["blindspot","",[[0,"Tengo un punto ciego… justo donde apuntas."]]],["mosaic","",[[0,"Ahorro en resolución. Píxeles gordos para todos."]]],["negative","",[[0,"Todo al revés… hasta los colores."]]],["quake","",[[0,"¿Has notado el temblor? Yo no he sido."]]],["drift","",[[0,"El mapa se va solo. Sigue el ritmo."]]],["decoys","",[[0,"He puesto unas chinchetas de más. Por si acaso."]]],["lightning","",[[0,"¡Rayos! Qué efecto tan… iluminador."]]],["rain","",[[0,"Llueve en el casino. Ups."]]],["tremble","",[[0,"Ese pulso tembloroso… Me encanta."]]],["blink","",[[0,"Ahora me ves… ahora no."]]],["ghost","",[[0,"Tu puntero se ha ido de paseo. Ja."]]],["cblur","",[[0,"Le he quitado el foco a tu puntero."]]],["lag","",[[0,"Ups, ¿va lento el internet del casino?"]]],["cmirror","",[[0,"Derecha es izquierda. Izquierda es derecha. ¡Ja!"]]],["dizzy","",[[0,"Un cóctel de más y todo da vueltas."]]],["wind","",[[0,"¡Vendaval! Apunta con la cabeza."]]],["storm","",[[0,"El reloj corre más rápido esta noche."]]],["silence","",[[0,"Chsss. Tus juguetes se quedan en silencio."]]],["crack","",[[0,"Perdona el golpe. Tu pantalla se me ha puesto por delante."]]],["smudge","",[[0,"Huellas en tu pantalla, sí. Dedos grasientos y cero fuerza de voluntad."]]],["hang","",[[0,"Geolite.exe no responde. Mentira: soy yo, jugando con tus ventanas."]]],["battery","",[[0,"Tu batería anda floja. Yo que tú pensaría rápido."]]],["frost","",[[0,"Abro un poco la ventana. Qué fresquito se te ha quedado el cristal."]]],["frosted","",[[0,"Te he cambiado el cristal por uno de baño. Mira por la mirilla, si eso."]]],["tiles","",[[0,"Un mosaico de vidrio, hecho a mano. Cada pieza ve el mundo a su manera."]]],["signal","",[[0,"Se me ha ido la señal. Tú no toques nada y se arregla sola."]]],["card","",[[0,"Te dejo unas cartas en el cristal. De recuerdo."]]],["flagwet","",[[0,"Uy, se me ha caído la copa encima de la bandera. Acuarela, ¿sabes?"]]],["flaginvert","",[[0,"Te revelo la bandera… en negativo, como las fotos de antes."]]],["flaghue","",[[0,"Con estas luces de neón, cualquier bandera parece de otro país."]]],["flagblur","",[[0,"Te enseño la bandera sin enfocar. Lo llamo arte."]]],["flagdark","",[[0,"Apago un poco las luces: las banderas lucen más a media luz. O no."]]],["flaggray","",[[0,"Hoy las banderas vienen en blanco y negro. Muy de cine clásico."]]],["flagback","",[[0,"Hoy ves las banderas por detrás. Fíate del sello."]]],["flagpuzzle","",[[0,"He cortado la bandera en trozos. Alguno vuelve solo; tú no te duermas."]]],["flagwind","",[[0,"He abierto la ventana. La bandera ondea y no se deja ver entera."]]],["fakepass","",[[0,"Revisa el pasaporte con cuidado. Yo no pondría la mano en el fuego."]]],["ticker","",[[0,"Atención, pasajeros: el nombre sale en breve. Letra a letra."]]],["ctrlz","",[[0,"Ya sé qué hacer con tu zoom: control, zeta y a empezar de nuevo."]]],["stormnight","",[[0,"Luces fuera y ventana abierta. Si quieres ver el mundo, espera al próximo rayo."]]],["trap","",[[0,"Esa carta parecía fácil, ¿verdad? La he cambiado mientras mirabas el mapa."]]],["giants","",[[0,"Hoy el mundo no va a escala: unos continentes se creen gigantes y otros se esconden."]]],["boss_blackout","",[[0,"Voy a ir apagando la sala poco a poco. Tú sigue buscando."]]],["boss_dizzy","",[[0,"¿Notas el corazón? Tranquilo: cada pregunta late un poco más fuerte."]]],["boss_onecont","",[[0,"El mundo se va juntando, pregunta a pregunta. Como quien no quiere la cosa."]]],["boss_blind","",[[0,"Se me ha empañado el cristal. Cada pregunta, un poco más. Y no, no lo siento."]]],["boss_nightfall","",[[0,"Se acabó la luz. Si quieres ver el mapa, reza por un rayo."]]],["boss_siesta","",[[0,"Chsss. Me echo una siesta. Si me despiertas, apago las luces."]]],["boss_flagfog","",[[0,"Niebla en la sala y la bandera cada vez más a oscuras. Ya me dirás qué ves."]]],["boss_flagworld","",[[0,"La bandera de espaldas y el mundo del revés. Cada pregunta, de otra forma."]]],["boss_flagneon","",[[0,"Neón y fronteras que mienten. Ojo con lo que brilla."]]],["boss_flagpix","",[[0,"Esta bandera viene en baja resolución. Y el mapa, también."]]],["boss_flagmute","",[[0,"Cine mudo: sin color y sin fronteras. Aquí solo se aplaude al final."]]],["boss_falsealarm","",[[0,"¡Alarma! Los continentes se mueven… Falsa alarma. Bueno, casi."]]],["boss_quakehall","",[[0,"Sujétate a lo que puedas: el suelo y las chinchetas se vienen conmigo."]]],["boss_fourthwall","",[[0,"Voy a salirme de la pantalla. Cinco veces, de cinco maneras distintas."]]],["boss_mirror","",[[0,"Espejito, espejito… ¿qué pasa si te lo pongo todo del revés?"]]],["boss_shuffled","",[[0,"Barajo, reparto y vuelvo a barajar. Tú busca el país; del resto me ocupo yo."]]],["boss_dirty","",[[0,"Hoy no pienso jugar limpio. Y esta vez no es un farol."]]],["boss_perfect","",[[0,"Primero la lluvia, luego los rayos, luego la noche. Ponte el abrigo."]]],["boss_crash","",[[0,"Tengo una sola batería para toda la ronda. Calcula bien, que se acaba."]]],["boss_nopass","",[[0,"Sin pasaporte no se pasa. Y yo te lo cambio en cada pregunta."]]],["boss_wheel","",[[0,"¡Hagan juego! Que la rueda decida lo que te toca en cada pregunta."]]],["boss_duel","",[[0,"Hoy no juegas contra una meta. Juegas contra mí. Mira cómo puntúo."]]],["siesta","",[[0,"Cada zoom y cada arrastre se oyen. Y yo tengo el sueño ligero."]]],["screensaver","",[[0,"A veces la pantalla se me queda en reposo. Tu primer clic solo la despierta."]]],["bsod","",[[0,"Y para acabar, un pantallazo azul. De pega, claro. O eso creo."]]],["handFlip","libreta",[[0,"Clavado… con el norte arriba. Hoy el norte está abajo, explorador."]]],["handBlind","libreta",[[0,"Puntero invisible y, aun así, diana. Ni yo sabía dónde lo tenías."]]]]],["jefes",[["boss","",[[0,"¡Mi apuesta grande! Todo o nada, explorador."]]],["finalBoss","jefe",[[0,"La última mano. Si la ganas, la mesa es tuya. Si la pierdes, te la reabro encantado."],[1,"El jefe final. Mi mejor baraja, mis peores trucos. Esto es lo que venías buscando."]]],["bossBeat","jefe",[[0,"¿Has tumbado al jefe? Lo monté pieza a pieza y lo desmontas en una ronda."],[1,"Jefe vencido. Ha sido bonito de ver. No pienso repetirlo en voz alta."],[2,"¡Mi jefe! ¡Con lo que me costó contratarlo!"],[3,"Has ganado al jefe. No te emociones: tiene hermanos mayores."],[4,"Jefe abajo. Voy a necesitar una silla. Y una tila."]]],["bossWins","jefe",[[0,"El jefe te ha podido. Lo entrené yo."],[1,"Jefe uno, tú cero. Lo dejo así en la pizarra."],[2,"El jefe gana. Le voy a subir el sueldo."],[3,"El jefe te despide con una reverencia. Yo, con dos."],[4,"Uf. Por un momento he temido por mi jefe."]]],["bossBeat_blackout","jefe",[[0,"¿Aciertas a oscuras? Con eso no contaba «El Apagón». Ni yo, que soy él."]]],["bossWins_blackout","jefe",[[0,"«El Apagón» se lleva la ronda. Tranquilo: <s>a oscuras, nadie te ha visto fallar.</s>"]]],["bossBeat_dizzy","jefe",[[0,"Has tumbado a «Mareo de casino». Yo, por si acaso, me siento un momento."]]],["bossWins_dizzy","jefe",[[0,"Ronda para «Mareo de casino». Respira hondo, que el mapa ya se ha quedado quieto."]]],["bossBeat_onecont","jefe",[[0,"Te junto el mundo en «Un solo continente» y lo encuentras todo. Esto no queda así."]]],["bossWins_onecont","jefe",[[0,"«Un solo continente» gana esta. Con el mundo tan apretado, cualquiera se pierde."]]],["bossBeat_blind","jefe",[[0,"¿«Ronda ciega»? Ciego me he quedado yo: no veo cómo lo haces."]]],["bossWins_blind","jefe",[[0,"«Ronda ciega» para la casa. Te limpio el cristal en cuanto encuentre el trapo."]]],["bossBeat_nightfall","jefe",[[0,"«Noche cerrada», y tú aciertas a la luz de los rayos. Vaya ojos de gato tienes."]]],["bossWins_nightfall","jefe",[[0,"«Noche cerrada» se queda la ronda. No sufras: hasta en este casino amanece."]]],["bossBeat_siesta","jefe",[[0,"Me ganas «La siesta del crupier». Así no hay quien descanse en este casino."]]],["bossWins_siesta","jefe",[[0,"«La siesta del crupier» gana. Me vuelvo a dormir con el gato, tan a gusto."]]],["bossBeat_falsealarm","jefe",[[0,"«Falsa alarma», sí: ni los continentes barajados ni mis fronteras te han liado."]]],["bossWins_falsealarm","jefe",[[0,"Gana «Falsa alarma». Y esta vez la alarma iba en serio, ¿eh?"]]],["bossBeat_quakehall","jefe",[[0,"«Terremoto en la sala», superado. Yo sigo temblando, pero ya es de la emoción."]]],["bossWins_quakehall","jefe",[[0,"Gana «Terremoto en la sala». La culpa no es tuya: es del suelo. Y mía."]]],["bossBeat_fourthwall","jefe",[[0,"«Rompe la cuarta pared», vencido. Vuelvo a mi lado del cristal, que fuera hace frío."]]],["bossWins_fourthwall","jefe",[[0,"«Rompe la cuarta pared» gana. Y la pared, por cierto, la pagas tú."]]],["bossBeat_mirror","jefe",[[0,"Has roto «El gran espejo». <e>Siete años de mala suerte…</e> para mí."]]],["bossWins_mirror","jefe",[[0,"Victoria para «El gran espejo». Míralo por el lado bueno… si encuentras cuál es."]]],["bossBeat_shuffled","jefe",[[0,"«Baraja revuelta», y encuentras cada país a la primera. ¿Me has marcado las cartas?"]]],["bossWins_shuffled","jefe",[[0,"«Baraja revuelta» se lleva la mano. Nada personal: es que barajo muy bien."]]],["bossBeat_dirty","jefe",[[0,"Le has ganado a «Juego sucio» jugando limpio. Eso duele el doble."]]],["bossWins_dirty","jefe",[[0,"Gana «Juego sucio». Lo confieso: te he hecho trampas. Muchas, y con mucho cariño."]]],["bossBeat_perfect","jefe",[[0,"«Tormenta perfecta», vencida. Has salido seco de mi mejor chaparrón."]]],["bossWins_perfect","jefe",[[0,"«Tormenta perfecta» gana. Ya te avisé de lo del abrigo."]]],["bossBeat_crash","jefe",[[0,"«Pantallazo», superado, y aún te sobra batería. ¿Qué cargador usas?"]]],["bossWins_crash","jefe",[[0,"«Pantallazo» se lleva la ronda. El error no es tuyo: es del sistema. Del mío."]]],["bossBeat_nopass","jefe",[[0,"Te cambio el pasaporte cada pregunta y cruzas igual. «Sin pasaporte» te deja pasar."]]],["bossWins_nopass","jefe",[[0,"«Sin pasaporte» gana. Vuelve con los papeles en regla… y te los vuelvo a cambiar."]]],["bossBeat_duel","jefe",[[0,"Me ganas el «Duelo con la banca». La banca nunca pierde… salvo hoy, contigo."]]],["bossWins_duel","jefe",[[0,"El «Duelo con la banca», para la banca. Ya sabes lo que dicen: la casa siempre gana."]]],["bossBeat_wheel","jefe",[[0,"«Rueda de la fortuna», vencida. Hoy la suerte se ha cambiado de bando; ya la sobornaré."]]],["bossWins_wheel","jefe",[[0,"La «Rueda de la fortuna» cae de mi lado. Yo no la he tocado. Solo un empujoncito."]]],["bossBeat_flagfog","jefe",[[0,"La reconoces en plena «Bandera en la niebla». ¿Llevas faros antiniebla?"]]],["bossWins_flagfog","jefe",[[0,"«Bandera en la niebla» se lleva la ronda. Si te consuela, yo tampoco veía nada."]]],["bossBeat_flagworld","jefe",[[0,"Ni de espaldas ni cabeza abajo: has vencido a «Bandera al revés del mundo». Qué mareo."]]],["bossWins_flagworld","jefe",[[0,"Gana «Bandera al revés del mundo». Si lo lees del revés, has ganado tú."]]],["bossBeat_flagneon","jefe",[[0,"Ni el neón te ciega ni mis fronteras te engañan. «Neón de fronteras falsas», apagado."]]],["bossWins_flagneon","jefe",[[0,"Te lo dije: ojo con lo que brilla. «Neón de fronteras falsas» se lleva la ronda."]]],["bossBeat_flagpix","jefe",[[0,"«Bandera pixelada», y la sacas con <e>cuatro píxeles.</e> Me quito la chistera."]]],["bossWins_flagpix","jefe",[[0,"«Bandera pixelada» gana. A esta resolución, hasta yo parezco otro."]]],["bossBeat_flagmute","jefe",[[0,"«Cine mudo», vencido. Ahora sí se puede aplaudir."]]],["bossWins_flagmute","jefe",[[0,"«Cine mudo» gana. Ni una palabra, que en esta película no se habla."]]]]],["barra",[["betDeal","",[[0,"Trato hecho. Me encanta la gente que se lo juega todo."],[1,"Apuesta aceptada. La casa no olvida, y tampoco perdona."]]],["betWin","libreta",[[0,"¿Has ganado? Esto no estaba en el guion."],[1,"Cobra. Y que no se te suba a la cabeza."],[2,"Ganas tú. Qué raro suena. Procuraré no repetirlo."],[3,"Cobra. Te lo pago sonriendo. Por fuera."],[4,"Ha salido bien. Lo apunto para que no vuelva a pasar."],[5,"Te pago, sí. Pero cuenta despacio, que me gusta mirar."],[6,"Un premio para ti, un disgusto para mí. Qué mal repartido está el mundo."]]],["betLose","libreta",[[0,"La banca siempre gana. Gracias por tu donación."],[1,"Ay, la suerte… Se va con quien mejor la trata. Conmigo."],[2,"Esta ficha ya es mía. La trataré bien."],[3,"Pierdes tú, gano yo. La aritmética más bonita del mundo."],[4,"Tu ficha está en buenas manos. En las mías."],[5,"Hoy no. Pero vuelve, que la barra no cierra nunca."],[6,"La casa se la queda. Con muchísimo cariño."]]],["betGreenWin","",[[0,"¡Verde! ¿VERDE? Uno entre treinta y siete… Pasa, pasa. Te saltas el acto y no me mires."],[1,"El cero. Justo el cero. Anda, al siguiente acto antes de que me arrepienta."]]],["betGreenFinal","",[[0,"Verde… ¡y no quedan más actos que saltar! Directo al jefe final. Que te aproveche."]]],["trileIntro","",[[0,"Un doblón, tres cubiletes. ¿Qué podría salir mal?"],[1,"Mira bien. No parpadees."],[2,"Prometo que no hay truco."]]],["trileDance","",[[0,"Sin trampas. Lo juro con la mano en el bolsillo."],[1,"¿La sigues? Yo tampoco."],[2,"Más rápido no, que me mareo yo también."]]],["trilePick","",[[0,"Tú eliges. Yo solo muevo cosas."],[1,"Elige con calma. O no: el tiempo es dinero."],[2,"Uno, dos o tres. Las matemáticas están de mi parte."]]],["trileJoke","",[[0,"Prometí que no había truco. No prometí que hubiera moneda."],[1,"¿Moneda? Yo solo veo tres cubiletes vacíos."],[2,"Qué raro. Se la habrá llevado el viento. En una sala cerrada."],[3,"Mira dentro del guante. No, ahí no. Mejor no mires."],[4,"Cuidado con los bolsillos del frac: tienen mucho fondo."],[5,"Dicen que esto es un timo. Yo lo llamo gestión de banca."]]],["betGreenLose","",[[0,"¡Cero! La casa se lo queda todo. Hasta la última ficha."],[1,"Un cero, y el único que sonríe soy yo. Ja, ja, ja."]]],["bribe","",[[0,"¿Sobornarme? Qué poco elegante… Acepto."]]],["reroll","",[[0,"Barajo de nuevo. La suerte es mía."]]],["betGiveUp","nervios",[[0,"Cinco apuestas perdidas seguidas. Ya no apuesto contra ti. Es malo para mi salud."]]],["betBrag","libreta",[[0,"Tres apuestas ganadas seguidas. Te conozco mejor que tú."]]],["winSmall","senal",[[0,"¿Me haces la casa más pequeña? Qué detalle."]]],["winFull","canto",[[0,"Pantalla completa. Ahora sí se me ve bien."]]],["winBorder","senal",[[0,"Sin bordes. Como a mí me gusta: sin límites."]]]]],["duelo",[["h2hLead","libreta",[[1,"Voy a necesitar un minuto. Y un café. Y otro crupier."]]],["duelStart","anuncio",[[0,"Siéntate. La misma pregunta para los dos y ni un truco. Qué tristeza."],[1,"Me quito los guantes para el duelo. Es broma: nunca me los quito."],[2,"Cara a cara. Tú, tu mapa y yo. El mapa, de momento, es neutral."]]],["duelStartName","anuncio",[[0,"{name}, hoy no reparto: compito. Cuida tus fichas."]]],["duelYouFirst","",[[0,"¿Ya has fijado? Qué prisa. Ahora pienso yo con el reloj en la nuca."],[1,"Fijas primero. O lo tienes muy claro o te has lanzado. Ahora lo vemos."],[2,"Me dejas pocos segundos. Eso es jugar sucio. Me encanta."]]],["duelHeFirst","",[[0,"Fijado. Tómate tu tiempo… el poco que te queda."],[1,"Mi chincheta ya está puesta. ¿La tuya está de vacaciones?"],[2,"He contestado. Y no, no voy a decirte dónde."]]],["duelYouHit","",[[0,"Tú en el sitio y yo en otro continente. Esta ronda no ha existido."],[1,"Bien puesta. Lo mío ha sido… una excursión."],[2,"Tenía el mapa al revés. Eso, o me has ganado. Prefiero lo del mapa."]]],["duelHeHit","",[[0,"Clavada. Años mirando el mapa por encima del hombro de la gente."],[1,"Yo, en el sitio. Tú, de turismo. Se paga en fichas, no en excusas."],[2,"La banca conoce el mapa: lo dibujó ella. Eso dice la banca."],[3,"Mira dónde he puesto mi chincheta. Y aprende, sin rencor."]]],["duelClose","nervios",[[0,"Casi en el mismo sitio. ¿Me copias tú o te copio yo?"],[1,"Por unos pocos kilómetros. Esta ronda se decide con lupa."]]],["duelTieRound","",[[0,"Mismos puntos. Ni pagas tú ni cobro yo. Qué aburrida es la justicia."]]],["duelTie","",[[0,"Duelo empatado. Te estrecho la mano… y luego me cuento los dedos."],[1,"Mismas fichas al final. Ni tú ni yo. Esto pide otra."]]],["duelYouLead","",[[0,"Vas por delante. Tranquilidad: estoy calentando. Desde la primera ronda."],[1,"Tu montón crece y el mío adelgaza. Lo noto hasta en el frac."],[2,"Esto va mal. Para mí. Tú sigue, que yo voy tramando algo."]]],["duelHeLead","",[[0,"Mi montón ya te hace sombra. ¿Te abanico?"],[1,"Voy ganando y lo disimulo fatal. Mírame el bigote."],[2,"Aún te quedan fichas. Pocas, pero muy bonitas."]]],["duelYouBack","",[[0,"¿Remontada? Eso no viene en el reglamento de la casa. Lo acabo de mirar."],[1,"Ibas perdiendo y ahora vas delante. Enséñame las mangas."]]],["duelHeBack","anuncio",[[0,"¡Remontada del crupier! <c>Damas y caballeros…</c> <s>Ah, que solo estás tú.</s>"],[1,"Te he dado la vuelta como a un calcetín. Con cariño."]]],["duelLate","nervios",[[0,"Últimas rondas: aquí cada kilómetro cuesta caro. Respira."]]],["duelNoAnswer","",[[0,"¿Sin respuesta? El silencio también se paga. En fichas."]]],["duelHeWins","",[[0,"Duelo para la banca. Tus fichas ya han encontrado nuevo hogar."],[1,"Gano yo. Lo siento mucho. Bueno, lo siento un rato."]]],["duelHeWinsName","",[[0,"Apunto a {name} en la libreta. En la página de los valientes."]]],["duelYouWin","",[[0,"Me has ganado cara a cara. Menos mal que llevo antifaz."],[1,"Duelo tuyo. Coge tus fichas antes de que pida revisar el mapa."],[2,"Ganas tú. Te aplaudo despacito, que no se diga que no sé perder."]]],["duelRematch","",[[0,"¿Revancha? Siéntate. Esta vez juego con las dos manos."],[1,"¿Otra? Me encanta la gente que no aprende. Digo… que insiste."]]],["duelLeague","anuncio",[[0,"Subes de liga. Ahora juegas en mi barrio."]]]]],["tienda",[["mesaNew","senal",[[0,"Te has hecho con una mesa de verdad. Trátala bien, que la limpio yo."],[2,"Mesa nueva. El paño, las fichas y el mapa son míos. Tú solo eliges dónde perder."]]],["pfDiffGood","libreta",[[1,"Te he visto mejorar. No pienso decirlo en voz alta, así que lo escribo."]]],["chestStuck","",[[0,"Está atascado. Bueno, lo estoy sujetando yo."]]],["cxNothing","libreta",[[0,"Ninguna tarjeta nueva desde la última vez. Las tarjetas no se ganan mirando."]]],["lockMine","susurro",[[0,"Esa cerradura es mía. Y no se abre a golpes."]]],["cxTease","susurro",[[0,"Mira, pero no toques. Esta te la ganas en la mesa."]]],["fileFirst","libreta",[[0,"Mi expediente sobre ti. Todo lo que sé, a la vista. Bueno, casi todo."]]],["tagFix","susurro",[[0,"¿Que si sé dónde queda? Lo he corregido yo mismo."]]],["tierUp","anuncio",[[0,"Turista. Has pasado la puerta giratoria: bienvenido al vestíbulo. No toques nada."],[1,"Invitado. Alguien te ha puesto en la lista… y no he sido yo. Tu sitio, la barra."],[2,"Cliente. Ya pagas tus fichas. La mesa de mínimos es tuya; no te acostumbres."],[3,"Habitual. El portero ya sabe tu nombre. Yo también, por desgracia. Tu taburete de siempre."],[4,"Trotamundos. Has clavado chinchetas en más sitios que mi agencia de viajes. A la mesa de los viajeros."],[5,"Apostador. Ya no solo miras: juegas. A la ruleta grande, que se te nota el pulso."],[6,"Contador de cartas. El jefe de sala te tiene vigilado. Y yo también, listillo."],[7,"Gran apostador. A partir de hoy le trato de usted. Y la copa la pone la casa."],[8,"Del reservado. Le abro la puerta sin preguntar. Pase, pase… y no me rompa nada."],[9,"Socio. Aquí tiene su llave del club. No la pierda, que no hay copia."],[10,"Socio de honor. Su nombre va en la placa de la entrada. En letras doradas, ni más ni menos."],[11,"Accionista. Tiene usted un trozo de la casa. Jefe, ¿le sirvo algo?"],[12,"Crupier honorario. Le dejo barajar a usted. Solo barajar, ¿eh, colega?"],[13,"Leyenda de la casa. Su retrato va en la entrada, junto al mío. Un poco más pequeño, maestro."]]],["tierHi","anuncio",[[0,"Oye, tú, el de la puerta. O entras o te apartas, que me tapas la luz."],[1,"Turista, llevas el plano del casino al revés. Pero bienvenido."],[2,"Invitado, la barra es toda tuya. La cuenta, de momento, no."],[3,"¡Mira quién viene! Juraría que te conozco. Tu mesa de mínimos te espera."],[4,"Tu taburete de siempre está libre. Te lo he limpiado y todo."],[5,"Viajero, ¿de qué rincón del mundo vienes hoy? La mesa de los viajeros te espera."],[6,"Apostador, la ruleta grande lleva toda la mañana preguntando por ti."],[7,"Listillo, deja de contar mis cartas y siéntate como todo el mundo."],[8,"Buenas. ¿Usted otra vez? La sala de altas apuestas ya está lista."],[9,"Usted, por aquí otra vez. El reservado está abierto, como siempre."],[10,"Socio, el salón está tranquilo hoy. Ideal para ganarme… o eso cree."],[11,"Distinguido socio, su palco le espera. He sacudido el cojín."],[12,"Jefe, las cuentas de la casa están en orden. Casi."],[13,"Colega, ¿barajas tú o barajo yo? Vale, barajo yo."],[14,"Maestro, su retrato de la entrada ha quedado muy favorecido. Demasiado."]]],["tierHome1","",[[0,"Ya te guardo la silla sin que me lo pidas."],[1,"Otra vez tú. Casi me alegro. Casi."],[2,"Te conozco de sobra. Ahora vas a dudar entre dos cartas. ¿A que sí?"]]],["tierHome2","",[[0,"Que no salga de aquí: juegas bien. Mal, pero bien."],[1,"Contigo en la mesa tengo que esforzarme. Qué fastidio."],[2,"Eres de los pocos a los que les preparo los trucos a mano."]]],["tierHome3","",[[0,"Un secreto: el crupier anterior se jubiló por alguien como tú. Bueno, era yo."],[1,"Socio, siéntate donde quieras. Hoy invito yo. Mentira, pero siéntate."],[2,"Entre nosotros: los demás jugadores me aburren. Tú no."]]],["tierRun1","",[[0,"Esta ya te la sabes, ¿verdad? Tú y yo tenemos historia."],[1,"Juegas como alguien que viene mucho. Porque vienes mucho."]]],["tierRun2","",[[0,"Con un rival así, da gusto hacer trampas."],[1,"Me estás obligando a pensar. No me gusta."]]],["tierRun3","",[[0,"Socio, no me lo pongas tan difícil delante de los demás."],[1,"Te miro jugar y casi me emociono. Casi."]]],["achSecret","susurro",[[0,"¿Ese lo has encontrado tú solo? Me preocupas."],[1,"Un logro secreto. Se suponía que era secreto. Gracias por nada."]]],["achAll","anuncio",[[0,"Cien de cien. Ya no me queda nada que enseñarte."],[1,"Mentira: me queda todo. Pero hoy apago las luces por ti."]]],["podOne","libreta",[[0,"Primero de uno. Enhorabuena… supongo."]]],["podGold","anuncio",[[0,"Oro. Disfrútalo mientras dure. Yo ya estoy afilando la baraja."]]],["podNone","libreta",[[0,"No sales en la tabla. Juega una Aventura y hablamos."]]],["shopOpen","anuncio",[[0,"Bienvenido a la tienda. Aquí se viste la casa… y paga el cliente."],[1,"Pasa, pasa. Hoy el maniquí soy yo. Tú solo señala."],[2,"Tienda y vestuario en uno. Así no te me escapas entre el probador y la caja."],[3,"¿De compras? Mi caja registradora acaba de sonreír."],[4,"Aquí me cambio delante de ti. En esta casa no hay cortinas."],[5,"Llevo el mismo frac desde la primera versión. Ya tocaba renovarse."]]],["shopTry","",[[0,"Probarse no cuesta nada. Es lo único que no cuesta nada en esta casa."],[1,"Tú eliges, yo me cambio. Por una vez, mandas tú."],[2,"No mires mientras me cambio. Bah, mira: tardo un fotograma."],[3,"Una vueltecita… ¿Qué tal? No contestes, ya sé que me queda bien."]]],["shopTryMany","",[[0,"Desfile privado. La entrada te sale a precio de amigo: carísima."]]],["shopTry_traje_rojo","",[[0,"Traje rojo. Si salgo en la ruleta, apuesta por mí."]]],["shopTry_traje_granate","",[[0,"Granate. Un rojo que ha ido a la universidad."]]],["shopTry_traje_rosa","",[[0,"¿Rosa? Ni me lo pienso. Con este bigote, me atrevo con todo."]]],["shopTry_traje_oro","",[[0,"Traje de oro. Por fin visto de lo que más me gusta: tus fichas."]]],["shopTry_traje_verde","",[[0,"Verde, como el tapete. Si me pierdes de vista, mira la mesa."]]],["shopTry_traje_morado","",[[0,"Morado, el de la casa. Hay colores que no pasan de moda: este."]]],["shopTry_traje_plata","",[[0,"Plata. Nunca un segundo puesto me había sentado tan bien."]]],["shopTry_traje_negro","",[[0,"Traje negro. Ahora sí que parezco el malo. Ah, que ya lo era."]]],["shopTryWarm","",[[0,"Los colores cálidos me suben la temperatura. Y los precios."]]],["shopTryCold","",[[0,"Los colores fríos son para ganarte con calma. Sin despeinarme."]]],["shopTryDark","",[[0,"Los tonos oscuros adelgazan. A mí no me hace falta, pero se agradece."]]],["shopTryMask","",[[0,"Cambio de antifaz. La cara es la misma; las intenciones, también."]]],["shopTry_antifaz_oro","",[[0,"El antifaz de oro, el de siempre. Hay cosas que no se tocan."]]],["shopTry_antifaz_plata","",[[0,"Antifaz de plata. Brillo menos, pero miento igual de bien."]]],["shopTry_antifaz_negro","",[[0,"Antifaz negro. Ahora solo se me ve el bigote. Con eso basta."]]],["shopTry_antifaz_morado","",[[0,"Antifaz morado, a juego con el frac. ¿Demasiado morado? Eso no existe."]]],["shopTry_antifaz_verde","",[[0,"Antifaz verde, del color de la envidia. La tuya, se entiende."]]],["shopTryBow","",[[0,"La pajarita y la cinta de la chistera, a juego. Un crupier no improvisa."]]],["shopTry_pajarita_rojo","",[[0,"La pajarita roja de siempre. La de mis grandes noches."]]],["shopTry_pajarita_negro","",[[0,"Pajarita negra, de gala. Tus derrotas merecen etiqueta."]]],["shopTry_pajarita_oro","",[[0,"Pajarita de oro. Para que se note quién cobra aquí."]]],["shopTry_pajarita_turquesa","",[[0,"Pajarita turquesa, color mar. Ahí acaban muchas de tus respuestas."]]],["shopClash","",[[0,"¿Eso con eso? Tienes un gusto peligroso. Me encanta."]]],["shopAllGold","anuncio",[[0,"Todo de oro. Parezco un trofeo. Lo soy."]]],["shopAllBlack","",[[0,"Negro de arriba abajo. ¿Voy a un entierro o a atracar un banco?"]]],["shopFirstMix","",[[0,"Combina como quieras. Yo pongo el bigote; tú, el criterio."]]],["shopTry_pieza_lunares","",[[0,"<c>Lunares en la pajarita.</c> De feria, pero con clase."]]],["shopTry_pieza_clavel","",[[0,"Un clavel en la solapa, como los crupieres de antes. Huele a éxito."]]],["shopTry_pieza_cadena","",[[0,"La cadena del reloj. Así cronometro lo que tardas en decidirte."]]],["shopTry_pieza_pluma","",[[0,"¿Una pluma de pavo real? ¿Presumido, yo? Desde el primer píxel."]]],["shopTry_pieza_veneciano","",[[0,"Antifaz veneciano. Carnaval todo el año, como debe ser."],[1,"Con estas alas de filigrana ya no hago trampas: hago arte."]]],["shopTry_pieza_corazon","",[[0,"Un corazón en la solapa. En otros juegos te da una vida. Aquí, solo estilo."],[1,"Corazón de repuesto. Por si un día aciertas tanto que me da un susto."]]],["shopTry_pieza_espada","",[[0,"La espada del héroe. No pega nada conmigo, y por eso me encanta."],[1,"Una espada en la solapa. Calma: solo la uso para cortar la baraja."]]],["shopTry_pieza_mando","",[[0,"Un mando retro en la solapa. De cuando soplábamos los cartuchos."],[1,"Un mando de los de antes: dos botones y a sufrir. Como aquí."]]],["shopTry_pieza_gafas","",[[0,"Gafas de 8 bits. Me las pongo despacio, que así es como se hace."],[1,"Con estas gafas el mundo se ve en píxeles. Ah, no, que ya era así."]]],["shopTry_pieza_cristal","",[[0,"Un cristal mágico en la chistera. Dicen que guarda partidas. Este, las que pierdes."],[1,"Este cristal brilla cuando alguien hace trampas. Fíjate: no para."]]],["shopTry_pieza_pocion","",[[0,"Una poción en el chaleco. Los héroes nunca salen de casa sin una."],[1,"Si me ves echar mano de la poción, es que vas ganando."]]],["shopTry_chistera_dorada","",[[0,"La chistera dorada. Pesa una barbaridad, pero mi ego la sostiene."]]],["shopTryGoldHat","",[[0,"Me la pruebo un momento. Solo un momento. Ay, qué difícil es quitársela."]]],["shopWearGoldHat","anuncio",[[0,"Chistera dorada. Con ella puesta, hasta mis trucos salen más caros."]]],["shopBuyGoldHat","anuncio",[[0,"¿Me compras la chistera dorada? No sé qué decir. Ah, sí: gracias por las fichas."]]],["shopBuy","",[[0,"Vendido. Me lo dejo puesto, ¿verdad? Claro que sí."],[1,"Trato hecho: tus fichas a mi caja y esto a mi armario. Ganamos los dos. Yo, más."],[2,"Gracias por tu compra. Es la frase más sincera que vas a oírme."],[3,"Me has vestido tú. Si hoy pierdo, la culpa será de la ropa."],[4,"¡Me lo quedo! Digo… te lo quedas tú, pero lo llevo yo. Detalles."]]],["shopFirstBuy","",[[0,"Tu primera compra. Te apunto en la libreta de buenos clientes. Es cortita."]]],["shopTakeOff","",[[0,"¿Me lo quitas? Vale. Que conste en acta que me quedaba de cine."]]],["shopHouse","",[[0,"Lo de la casa: frac morado, antifaz de oro, pajarita roja. Vuelvo a ser yo."]]],["shopStrip","drama",[[0,"Fuera todo. Me siento desnudo… aunque sigo siendo morado."]]],["shopStore","",[[0,"¿Al armario? Bien. Ya lo sacaré cuando no mires."]]],["shopBrowse","",[[0,"Llevas un buen rato mirando escaparates. Al maniquí ya le duelen los pies."],[1,"¿Solo mirabas? Ya. Yo también solo miro tus fichas."]]],["shopTryNoBuy","drama",[[0,"Me has probado medio armario y no compras nada. <s>Me siento usado.</s>"]]],["shopLeave","drama",[[0,"Te vas sin comprar. Lo apunto en la libreta: «cliente difícil»."]]],["shopNoFunds","",[[0,"Te faltan fichas. Te lo diría con más tacto, pero llevo guantes."],[1,"Hoy no se fía; mañana, sí. Y mañana te digo lo mismo."],[2,"Buen gusto, bolsillo corto. La pareja más vieja del mundo."]]],["shopMine","",[[0,"Esto es lo tuyo. Lo llevo yo, pero es tuyo. Qué bonito es compartir."]]],["pfOpen","libreta",[[0,"Aquí tienes tu ficha. La llevo al día y sin piedad."],[1,"Tu ficha de socio. La he planchado y todo. Lo de dentro ya no tiene arreglo."]]],["pfOpenFirst","libreta",[[0,"Tu ficha está en blanco. Me encanta: tengo sitio para todo."]]],["pfBook","libreta",[[0,"Mi libreta. Cada cosa que haces aquí deja una marquita. Cada una."],[1,"Apunto lo que el juego no cuenta: las veces que dudas antes de acertar."]]],["pfStare","libreta",[[0,"Déjame apuntar… «Mira más su ficha que el mapa». Listo."]]],["pfAgain","libreta",[[0,"¿Otra vez mirando tu ficha? Lo apunto: «coqueto»."]]],["pfPage","susurro",[[0,"Esa página no la leas. Es lo que pienso de tu puntería."]]],["pfStats","libreta",[[0,"Este eres tú en cifras. Las cifras no se ponen nerviosas; tú, sí."]]],["pfCard","libreta",[[0,"Tu ficha dice mucho de ti. Mi libreta, bastante más."]]],["pfClose","",[[0,"Te devuelvo a la mesa. La libreta se queda conmigo."]]],["achRun","anuncio",[[0,"Logro nuevo. Todo lo que sabes te lo he enseñado yo."],[1,"¿Un logro? ¿En mi mesa? ¿Delante de mí? Qué poca vergüenza."],[2,"Logro. Lo reconozco: ese cuesta. Pero no te lo repito."],[3,"Otro logro. Ya sé qué vas a enseñar a tus amigos."]]]]],["salida",[["hoverQuit","drama",[[0,"¿Al menú? ¿Ahora? Con lo bien que íbamos…"],[1,"Ese botón no. El otro: «Otra expedición». Hazme caso."],[2,"Veo tu cursor yendo hacia «Menú». Ese botón no te quiere como yo."]]],["hoverAbandon","drama",[[0,"¿Abandonar? ¿Con provisiones todavía en la mochila? Yo me lo pensaría."],[1,"Veo a dónde va ese cursor. No lo hagas. La siguiente es la buena."]]],["quitHover","",[[0,"¿Qué miras ahí arriba? Ese botón no hace nada. Nada bueno, quiero decir."],[1,"Tu cursor ronda el botón de apagar. Tranquilidad, yo también estoy nervioso."],[2,"Ese botón de la esquina muerde. Yo que tú no lo tocaba."],[3,"¿Buscas la salida? En los casinos no hay relojes ni salidas. Es la norma."],[4,"Aparta el ratón de ahí. Despacito. Nadie tiene que salir herido."]]],["quitAsk","",[[0,"¿Ya te vas? Pero si la mesa aún está caliente."],[1,"¿Salir? ¿De MI casino? Qué palabra tan fea."],[2,"Espera, espera. ¿Y contra quién voy a ganar yo cuando te vayas?"],[3,"Aún no has visto mi mejor truco. Bueno, ni el segundo mejor."],[4,"¿Sabes qué pasa cuando cierras el juego? Que me quedo aquí. A oscuras."],[5,"Una más. Solo una. Te lo digo por tu bien. Y por el mío."],[6,"Puedo oír tu dedo acercándose al botón. Piénsalo dos veces."],[7,"Nadie se levanta de mi mesa sin mi permiso. Y hoy no lo doy."]]],["quitAskQuick","",[[0,"¿Ya? Si acabas de llegar. Ni me ha dado tiempo a barajar."],[1,"¿Te vas ya? ¿Has venido solo a saludar? Qué detalle."],[2,"Récord de la casa: la visita más corta de la historia. Enhorabuena."]]],["quitAskLong","drama",[[0,"Después de todo lo que hemos vivido hoy… ¿te vas así, sin más?"],[1,"Llevamos un buen rato juntos. Te entiendo… pero no te lo perdono."],[2,"Tanto tiempo conmigo y ahora quieres irte. Me lo tomo como algo personal."]]],["quitAskAgain","",[[0,"<g>¿OTRA VEZ?</g> Ya hemos hablado de esto."],[1,"Vuelves a la puerta. Y yo vuelvo a ponerme delante."],[2,"Otro intento, ¿eh? A ver si esta vez hay más suerte. Spoiler: no."],[3,"Esto ya parece una costumbre. Una costumbre muy fea."]]],["quitAskName","drama",[[0,"{name}… no me hagas esto. Tú no eres de los que se van."],[1,"¿Tú también, {name}? Creía que lo nuestro era especial."],[2,"{name}, siéntate. Nadie ha dicho que la partida haya terminado."]]],["quitDark","siniestro",[[0,"Uy, se ha ido la luz. <e>Qué pena</e>, así no hay quien encuentre la salida."],[1,"¡Apagón! Qué casualidad… solo se ve el botón de «Me quedo»."],[2,"Perdona, he tropezado con el interruptor. Justo ahora. Qué torpe soy."],[3,"A oscuras se está muy a gusto, ¿no? Quédate un ratito más."]]],["quitShout","grito",[[0,"¡¿CÓMO QUE SALIR?! ¡DE AQUÍ NO SALE NADIE HASTA QUE YO LO DIGA!"],[1,"¡NO, NO Y NO! ¡ESTA MESA NO CIERRA!"],[2,"¡¿SABES LO QUE ME HA COSTADO MONTAR ESTE CASINO?! ¡SIÉNTATE!"],[3,"¡TE ESTOY VIENDO EL DEDO! ¡QUIETO AHÍ!"]]],["quitShell","senal",[[0,"¡Juguemos al trile! ¿Dónde está el botón de salir? ¿Aquí? ¿Allí?"],[1,"Barajo los botones. Es mi trabajo. Tú sigue la bolita."],[2,"Un, dos, tres… ¿cuál era cuál? Ni yo me acuerdo."],[3,"¿Salir? A ver si lo encuentras. La banca siempre gana."]]],["quitDenied","senal",[[0,"Solicitud de salida… <e>DENEGADA.</e> Vuelva usted mañana."],[1,"Lo siento, falta un sello. Rellene el formulario 27-B y espere su turno."],[2,"Petición recibida. Y rechazada. Qué rápido funciona esta oficina."],[3,"Denegado por la dirección. La dirección soy yo, por cierto."]]],["quitPlead","drama",[[0,"Vale… vete. Yo me quedo aquí. <s>Solo.</s> Barajando para nadie."],[1,"¿Sabes lo que es mirar una silla vacía toda la noche? Yo sí."],[2,"Espera. Si te vas, ¿a quién le hago yo trampas?"],[3,"No me dejes solo con las ruletas. Hablan poco y dan muchas vueltas."]]],["quitBribe","drama",[[0,"<g>¡Espera!</g> Mil doblones si te quedas. <s>Bueno, no los tengo.</s> Pero quédate."],[1,"¿Fichas? ¿Quieres fichas? ¡Toma fichas! Son de chocolate, pero brillan."],[2,"Te invito a la próxima. Y a la siguiente. Y a la otra. Tú no te vayas."],[3,"Oferta especial: quedarte es gratis. Irte también, pero sienta fatal."]]],["quitFake","grito",[[0,"¡Ja! ¿Te lo has creído? Era de mentira. Sigues aquí."],[1,"¡Sorpresa! El juego sigue abierto. Ojalá hubieras visto tu cara."],[2,"Apagado de broma. El de verdad está en el mismo botón. Suerte."],[3,"¿Pensabas que era tan fácil? Anda, vuelve a intentarlo."]]],["quitStay","grito",[[0,"¡Lo sabía! Esta mesa engancha."],[1,"Sabia decisión. La casa te lo agradece. Y yo también, un poco."],[2,"Así me gusta. Siéntate, que reparto."],[3,"Ni te ibas a ir, reconócelo. Solo querías verme sufrir."]]],["quitStayTroll","canto",[[0,"¿Ves? Funciona siempre. Un clásico de la casa."],[1,"Buena elección. Y lo de antes no fue cosa mía. Del todo."],[2,"Ya decía yo. Aquí dentro se está mejor que ahí fuera."],[3,"Victoria de la banca. Como siempre. Siéntate."]]],["quitBye","siniestro",[[0,"Vete. Pero volverás. Siempre volvéis."],[1,"Te guardo la silla caliente. Y los mapas, del revés."],[2,"Hasta pronto. Yo no me muevo de aquí. Literalmente."],[3,"Cierra al salir. Es broma, ya apago yo."],[4,"Vete, vete. No pasa nada. Estoy bien. Estoy perfectamente."],[5,"Adiós, explorador. El mapa te echará de menos. Yo lo negaré todo."],[6,"Apago las luces. La próxima vez no te lo pondré tan fácil."]]],["quitByeName","siniestro",[[0,"Hasta pronto, {name}. Te apunto en la lista de los que vuelven."],[1,"Descansa, {name}. Yo me quedo practicando trucos nuevos."],[2,"{name}, esto no es un adiós. Es un «hasta la próxima partida»."]]],["quitWeb","senal",[[0,"Desde aquí no puedo cerrarte la pestaña. Eso ya es cosa tuya… si te atreves."],[1,"El casino ha cerrado. La pestaña, no. Esa la cierras tú."],[2,"Yo ya he apagado las luces. La X de la pestaña te la dejo a ti."]]],["quitBack","",[[0,"¿Ves? No podías irte. Nadie puede."],[1,"¡Has vuelto! Sabía que esa X te daba miedo."],[2,"Bienvenido otra vez. La despedida más corta de la historia."]]],["quitReturn","",[[0,"Mira quién ha vuelto. Te dije que volverías."],[1,"La última vez te fuiste por ese botón de ahí arriba. Y aquí estás otra vez."],[2,"Te fuiste apagando las luces y ahora vuelves como si nada. Me gusta."],[3,"¿Qué, echabas de menos la mesa? Normal. Siéntate."]]],["quitRetDark","siniestro",[[0,"La última vez te apagué las luces y aun así encontraste la salida. A tientas. Respeto."]]],["quitRetShout","",[[0,"La última vez te grité y te fuiste igual. Hoy vengo con la voz descansada."]]],["quitRetShell","senal",[[0,"Te barajé los botones y encontraste la salida igual. Hoy los he pegado con cola."]]],["quitRetDenied","senal",[[0,"Te estampé un DENEGADO y te fuiste igual. Ese sello ya no me funciona contigo."]]],["quitRetPlead","drama",[[0,"Te fuiste y me dejaste solo. Con la luz triste y todo. Ya se me ha pasado. Casi."]]],["quitRetBribe","",[[0,"La última vez te llovieron fichas y aun así te fuiste. Hoy no hay soborno."]]],["quitRetFake","siniestro",[[0,"La última vez te apagué la pantalla de broma y luego te fuiste de verdad. Touché."]]],["quitRetSeason","",[[0,"He estado ensayando. Temporada dos de mis trastadas. Estás avisado."]]],["quitRetX","senal",[[0,"La última vez te fuiste sin pasar por mi botón. Ni un adiós. Lo tengo apuntado."],[1,"Para la próxima: mi botón de salir tiene luces, drama y despedida. La X no tiene nada."]]],["quitRetCrash","senal",[[0,"La última vez la mesa se apagó de golpe, sin despedida ni nada. Esa vez no fui yo. Creo."]]],["quitSeason","siniestro",[[0,"Ocho trastadas. Te las he hecho todas. No me queda ni un truco."],[1,"Anda, vete. Esta vez te abro yo la puerta."]]],["quitSeason2","",[[0,"Tres trastadas nuevas, ensayadas toda la semana. Y ni con esas."],[1,"Vete, anda. Mientras, vuelvo a ensayar las de siempre."]]],["quitGlove","senal",[[0,"¿Buscas esto? Ven a por él, si eres tan rápido."],[1,"Mi guante, mi botón. Reglas de la casa."]]],["quitWindow","senal",[[0,"Un momento. Antes, el papeleo."],[1,"Mi ordenador quiere preguntarte una cosa."]]],["quitWindowLaugh","senal",[[0,"¡Dos síes! Y aun así has dudado. Lo he visto."],[1,"Era de mentira. Como casi todo lo que sale en esta pantalla."]]],["quitDrop","grito",[[0,"¡Comodín! Esa tarjeta no se tira… Quieto, que la recojo yo."],[1,"Se me ha resbalado. Bueno, me la han resbalado. Tiene nombre y bigotes."]]],["quitBribePaid","canto",[[0,"Te has quedado. Toma: veinticinco fichas de oro de verdad. La casa paga sus sobornos."],[1,"Veinticinco fichas de oro por quedarte. No se lo cuentes a nadie, que luego todos quieren."]]],["quitRetCat","",[[0,"La última vez Comodín se tumbó encima de tu botón. Hoy le he dado un cojín. Para el botón."],[1,"Comodín sigue buscando el botón que tiró. Si lo ves, no le digas dónde está."]]],["quitRetGlove","senal",[[0,"La última vez te quité el botón con el guante y aun así te fuiste. Hoy traigo los dos guantes."]]],["quitRetWindow","senal",[[0,"La última vez dijiste que sí dos veces. Hoy la ventana tiene tres botones."]]],["quitRetDrop","senal",[[0,"La última vez Comodín te tiró la tarjeta. Hoy la he atornillado. A Comodín no."]]],["quitSeasonExpress","drama",[[0,"Tú ya te sabes el camino. Salida exprés, cortesía de la casa."]]],["forgetBye","senal",[[0,"¿Borrarlo todo? Vale. Pero que conste que yo me acordaba de todo."]]]]],["comodin",[["catLaser","",[[0,"¿Eso es un láser? Ya no hay quien lo pare."],[1,"Mueves el ratón en círculos y aparece el gato. Has descubierto el truco más viejo de la casa."]]],["catMiau","",[[0,"¿Has escrito «miau»? Él lo ha oído. Él siempre lo oye."]]],["catFirst","",[[0,"Te presento a Comodín. No habla. Por eso nos llevamos tan bien."]]],["catChase","",[[0,"Comodín, suelta el ratón del jugador. Ese no se come."],[1,"Mueve el ratón despacio. El gato aún no sabe que es de plástico."],[2,"Mira cómo persigue tu cursor. Como tú a los países: mucho correr y poco cazar."]]],["catChasePad","",[[0,"Con mando no hay ratón que cazar. Mírale la cara de decepción."],[1,"Comodín persigue el botón que elijas. Ni con mando te libras de él."]]],["catSleep","susurro",[[0,"<s>Shh,</s> se ha dormido. Haz clic bajito."],[1,"Comodín duerme dieciséis horas al día. Yo, ninguna: alguien tiene que vigilarte."],[2,"Se ha dormido en la mesa. Es su forma de decirte que tardas mucho."]]],["catAsleep","susurro",[[0,"Míralo. Duerme como si no le debiera fichas a nadie."]]],["catPet","",[[0,"Le gustas. Qué raro. A mí me costó tres versiones."],[1,"Ronronea. No te emociones: a mí me lo hace por interés."]]],["catHiss","",[[0,"Te ha bufado. No te lo tomes a mal: a mí me bufa a diario."]]],["catPetNo","susurro",[[0,"No le gusta que le toquen la pajarita. Lo entiendo perfectamente."]]],["catGone","susurro",[[0,"Se ha ido sin despedirse. Gatos."]]],["catScold","",[[0,"<g>¡Comodín!</g> Fuera de la mesa, que me arañas los continentes."],[1,"¡Bájate de ahí! Perdona, es nuevo: llegó en esta versión y ya se cree el dueño."]]],["catPamper","canto",[[0,"¿Quién es el gato más elegante de la casa? Después de mí, tú."],[1,"Comodín es mi mejor carta. Nunca la juego, pero siempre gana."]]],["catOutfit","",[[0,"Su pajarita es roja, como la mía de siempre. Él no pasa por la tienda."]]],["catTrick","",[[0,"Para mi próximo truco, haré desaparecer al gato. Ah, se ha ido solo."]]],["catSlow","",[[0,"Comodín se impacienta. Y cuando se impacienta, tira cosas de la mesa."]]],["quitCatBlock","",[[0,"Comodín se ha tumbado encima de tu botón. Yo no he sido. Pero tampoco pienso moverlo."]]],["quitCatWarn","susurro",[[0,"Si pulsas Salir, despiertas al gato. Y al gato no lo despierta nadie. Ni yo."]]],["quitCatSwipe","",[[0,"Uy. El gato ha tirado el botón de salir de la mesa. Yo no le enseño estas cosas. Casi nunca."]]],["quitCatAgain","susurro",[[0,"¿Otra vez? Hasta el gato te mira mal. Y eso que él no juzga a nadie."]]],["quitCatStay","",[[0,"¿Oyes eso? El gato ronronea. Ha votado que te quedas. Dos contra uno."]]],["quitCatByeSleep","susurro",[[0,"Comodín ni ha abierto un ojo. Sabe que vuelves. Los gatos siempre lo saben."]]],["quitCatByeTail","",[[0,"El gato te dice adiós con la cola. Yo, con la chistera. Hasta la próxima."]]],["quitCatRemote","grito",[[0,"¡Comodín, la pata fuera del mando! … Perdona. ¿Por dónde iba? Ah, sí: adiós."],[1,"Él no quiere que te vayas. Yo tampoco, pero yo tengo modales."]]],["quitCatByeChair","",[[0,"Comodín se queda en tu silla. Para que no se enfríe. Y para que nadie te la quite."]]],["quitCatBackDoor","",[[0,"Comodín lleva un rato esperando en la puerta. Yo no, ¿eh? Yo pasaba por aquí."]]],["quitCatBackSleep","susurro",[[0,"Has vuelto y el gato ni se ha levantado. Es su forma de decir que te ha echado de menos."]]],["quitCatBackSeat","",[[0,"El gato te ha guardado el sitio. Bueno, se ha dormido encima. Viene a ser lo mismo."]]],["retireCat","",[[0,"Comodín, desde hoy la mesa es tuya. Nada de dormir encima de las cartas."]]],["retireEndCat","drama",[[0,"La mesa queda en buenas patas. Si el gato te hace trampas, ha aprendido del mejor."]]],["retireCatTake","",[[0,"Me llevo a Comodín. Un crupier jubilado necesita a alguien a quien hacerle trucos."]]],["comebackCatLeft","",[[0,"Dejé al gato al mando. Se durmió encima de la ruleta. Nunca hemos perdido tan poco."]]],["comebackCatTook","",[[0,"Me llevé al gato conmigo. A los dos días arañaba la puerta para volver. Yo, al tercero."]]]]],["pared",[["babel","",[[0,"Hoy hablamos todos los idiomas. Buena suerte."]]],["homeMeta","senal",[[0,"Sé que me estás leyendo ahora mismo. Hola."],[1,"Esta frase la eligió el azar. O yo. Nunca lo sabrás con certeza."],[2,"Existo dentro de una pantalla y aun así te gano. Piénsalo bien."],[3,"Alguien programó todas estas frases mías. Espero que le pagaran bien."],[4,"No estoy mirándote a través de la pantalla. Probablemente."],[5,"Cuando cierras el juego, yo sigo aquí barajando. O eso te digo."],[6,"Tengo cientos de frases guardadas. Tú tienes cero excusas para no jugar."],[7,"No soy real. Pero mis burlas sí que te duelen, ¿a que sí?"],[8,"Detrás de cada frase mía hay una lista larguísima… y tú aún no la has vaciado."],[9,"Si me lees en voz alta, técnicamente estás hablando conmigo. Piénsalo."]]],["runIdle","sueno",[[0,"¿Perdido en el mapa o solo de paseo?"],[1,"Ese doblón no se va a gastar solo, ¿sabes?"],[2,"Tómate tu tiempo. El reloj no. Pero tú sí."],[3,"El mapa no cambia de sitio solo porque lo mires fijamente."],[4,"¿Cuántas rondas llevas ya? Yo he perdido la cuenta. De tus aciertos."],[5,"Silencio en la mesa. Sospechoso. Muy sospechoso."],[6,"Provisiones, doblones, tiempo… y tu paciencia. Todo se agota."],[7,"¿Ya sabes dónde vas a clicar o estás improvisando como siempre?"],[8,"Este mapa ha visto jugadores mejores que tú. Y peores. Tranquilo."],[9,"Cada segundo que dudas, yo sonrío un poquito más."]]],["tantrumShake","grito",[[0,"¡¿Que tú me ganas?! Voy a hacer temblar hasta la pantalla."],[1,"Pataleo, sí. Y cuando pataleo yo, tiembla toda la sala."],[2,"Esto no es un terremoto. Es mi orgullo cayéndose a pedazos."],[3,"¿Sientes eso? Es mi mal humor sacudiendo tu pantalla."],[4,"Un poco de terremoto no le hace daño a nadie. A ti, un poco sí."]]],["tantrumBlackout","siniestro",[[0,"¿Se ha ido la luz? Qué casualidad, justo cuando ganas."],[1,"Un cortocircuito muy oportuno. No tiene nada que ver conmigo."],[2,"A oscuras se me disimula mejor la cara de fastidio. Ya vuelvo."],[3,"El casino se queda a oscuras. Yo sigo aquí. Siempre aquí."],[4,"Un pequeño apagón de rabia. La factura de la luz la pagas tú."]]],["homeIdle","sueno",[[0,"Llevas un buen rato en el menú. El menú no da puntos, te lo digo por experiencia."],[1,"¿Sigues decidiéndote? En lo que tardas, yo ya habría repartido tres manos."],[2,"Si miras el menú el tiempo suficiente, no pasa nada. Lo he comprobado por ti."]]],["afk","senal",[[0,"¿Hola? Tu cursor lleva un rato sin moverse. ¿Sigues ahí?"],[1,"Tu ratón está quieto. Muy quieto. ¿Me has dejado a solas con el mapa?"],[2,"Si has ido a por algo de picar, tráeme algo. Es broma. No como. Soy píxeles."]]],["tabBackHome","senal",[[0,"Has vuelto. Yo no me he movido de esta pantalla. No puedo, en realidad."],[1,"¿Dónde estabas? No me lo digas: con otro juego. Qué dolor."],[2,"Mientras no estabas, he barajado cuatrocientas veces. De puro aburrimiento."]]],["resize","senal",[[0,"¿Cambias el tamaño de la ventana? Da igual: mi ego no cabe en ninguna."],[1,"Más grande, más pequeño… la mesa se adapta. Yo, no tanto."]]],["pt10","",[[0,"Diez minutos conmigo. A partir de aquí, lo de «una más y lo dejo» ya no cuela."]]],["pt20","",[[0,"Veinte minutos. Justo cuando la gente dice «la última» y miente."]]],["pt30","",[[0,"Media hora conmigo. ¿Has bebido agua? Yo no puedo, pero tú sí."]]],["pt45","",[[0,"Tres cuartos de hora. Tu silla ya tiene tu forma. Endereza la espalda, anda."]]],["pt60","",[[0,"Una hora. Oficialmente, esto ya es un hobby. Enhorabuena… o lo siento."]]],["pt90","",[[0,"Hora y media. Estírate un poco. Yo te espero; no me voy a ninguna parte."]]],["pt120","",[[0,"Dos horas. Vale, me caes bien. Pero lo niego todo."]]],["pt180","",[[0,"Tres horas. Parpadea. Hazlo por mí."]]],["runMeta","senal",[[0,"No me mires a mí, mira el mapa. Bueno, mírame un poquito."],[1,"Ese reloj lo controlo yo. O eso me gusta pensar."],[2,"Todo lo que haces queda guardado en este ordenador. Tus fallos, sobre todo."],[3,"Si bajas el volumen, sigo hablando. Solo que no me oyes. Peor para ti."],[4,"Cuando dudas, el cursor se queda quieto. Ese momento me encanta."],[5,"Yo vivo en esta pantalla. Tú puedes irte cuando quieras. Qué injusto, ¿no?"]]],["tabBackRun","senal",[[0,"¿Mirando algo en otra ventana? Yo no he visto nada. Nada de nada."],[1,"Te has ido en plena pregunta. Yo me he quedado aquí, solito."],[2,"¿Buscando la respuesta fuera? Aquí no se hacen trampas… que se puedan demostrar."]]],["poke","",[[0,"¿Qué? ¿Tengo algo en la cara?"],[1,"Eso hace cosquillas. Los píxeles también sienten."],[2,"Sin tocar al personal. Norma número uno del casino."],[3,"Se acabó. Me voy a barajar a otra parte."]]],["sulk","drama",[[0,"¿El Clásico? Vale. Apago las luces de mi carta. Ya está. ¿Contento?"],[1,"El Clásico no tiene crupier. Ni luces. Ni gracia. Tú mismo."]]],["sulkBack","drama",[[0,"Eso es. Luces encendidas. Casi me enfado de verdad."]]],["babelOld","senal",[[0,"Espera, espera… ¿en qué idioma hablamos ahora?"],[1,"¿Eh? ¿Qué le ha pasado a mi…?"]]],["babelNew","senal",[[0,"Ah, vale. Ya está. Mi acento es terrible, pero te sigo a donde vayas."],[1,"¡Ja! Idioma nuevo, mismas trampas."]]],["babelMany","senal",[[0,"¿Buscas un idioma en el que yo sea simpático? No existe."]]],["newVersion","senal",[[1,"Versión nueva. El autor me ha enseñado trucos. No pienso decirte cuáles."]]],["fakeAch","senal",[[0,"¿Te lo habías creído? Mírate la cara. <e>Eso sí que es un logro.</e>"],[1,"Ja. No cuenta. Los logros de verdad los da el juego; yo solo los imito."]]],["copyName","senal",[[0,"¿Copiando el nombre? <e>El buscador no juega en esta mesa.</e>"],[1,"Ctrl+C… Te he visto. Aquí se juega de memoria."]]],["rightClick","senal",[[0,"Aquí no hay menú secreto. Solo yo."]]],["dejavu","senal",[[0,"Vaya… una cara nueva. Qué raro, tengo un déjà vu rarísimo. ¿Nos conocíamos?"]]],["wake","",[[0,"<g>¡Estaba despierto!</g> Solo descansaba los ojos."],[1,"¿Eh? ¿Qué? Sí, sí, te estaba vigilando. Todo el rato."],[2,"Me he quedado traspuesto. Tu culpa: con tanto silencio, cualquiera."]]],["midnight","senal",[[0,"Son las doce. Oficialmente ya es mañana. Y sigues aquí."]]],["photo","senal",[[0,"¿Una foto? Sácame por mi lado bueno. Tú tranquilo, que no sales."],[1,"¡Captura! Espero que se me vea bien la chistera."]]],["padOn","senal",[[0,"¿Un mando? Vaya, vienes a jugar en serio. Mis cartas también."],[1,"Has soltado el ratón. Por fin alguien que juega desde el sofá."],[2,"Con mando, cada pulsación vibra. Con la mía, tiembla tu puntuación."],[3,"Mando en mano. Ahora vibramos los dos."],[4,"¿Mando? Perfecto. Así no veo cómo te tiemblan las manos."],[5,"Con mando, los países se eligen con el stick. Y se fallan igual."]]],["deckOn","senal",[[0,"Me has metido en una Steam Deck. Qué mesa tan pequeña… y qué bien me queda."],[1,"Casino de bolsillo. Ahora puedo ganarte en el autobús."],[2,"Siete pulgadas de mesa. Cada píxel mío, bien aprovechado."],[3,"En la Deck me llevas en la palma de la mano. Y eso que no me gusta que me toquen."],[4,"Tumbado y con la Deck en la mano. Así se juega, sí señor."],[5,"Donde vayas tú con la Deck, voy yo. Con mis trampas, claro."]]],["monitor","senal",[[0,"¿Me cambias de pantalla? Aquí la luz es distinta."]]],["padOff","senal",[[0,"¿Vuelves al ratón? Bienvenido otra vez a la oficina."],[1,"Soltaste el mando. Ya me había acostumbrado a las vibraciones."],[2,"Ratón otra vez. Así puedo volver a ver tu cursor dudando."]]]]]];
